{
  "story": "How does a hash table retrieve a value without scanning every entry? Start with three stored entries and request “act.” Hash the key, follow its bucket, and compare the chained keys. Watch “cat” fail before “act” matches: sharing a bucket never makes two keys interchangeable.",
  "aha": {
    "stateId": "found",
    "observation": "Hashing selects a bucket; exact key comparison distinguishes colliding keys and retrieves the correct value."
  },
  "layout": {
    "preset": "approved-card/stepper-states/collection",
    "width": 640
  },
  "parts": [
    {
      "id": "lookup-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation, above the picture. Show the active step and completed-step trace here, without suggesting elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "lookup-table",
      "kind": "fixed-picture",
      "presentation": "Use tested collection parts within the approved shell. Keep the query, hash function, four buckets, and linked entries fixed throughout. Show each entry's key and stored value. Highlight only the bound active regions. Bucket labels are zero-based addresses. Fixed inputs use case-sensitive keys and an intentionally weak character-count hash. Separate chaining preserves entry order. No insertion, deletion, or resizing occurs. Reserve label space at native width; do not animate.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "lookup-callout",
      "kind": "active-callout",
      "presentation": "Anchor text beside its target without covering entries. Callout text identifies location only. Put the bound reason above the experiment.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "lookup-readouts",
      "kind": "value-readout",
      "presentation": "Place compact readouts below the picture. Render Status as the bound status line. Hash outputs are zero-based bucket indices. Comparisons count exact key-equality tests; integers require no rounding. Balanced parameter-control budget: zero, excluding navigation and reset.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "lookup-step",
      "kind": "index",
      "presentation": "Use Previous and Next, retaining both names when disabled at boundaries. Default to the first state; advance one state within array bounds. Every state, including found, persists until learner action. Reference captures show found. Provide matching accessible names, keyboard operation, and visible focus.",
      "items": "variant.states",
      "label": "Lookup step"
    },
    {
      "id": "reset",
      "kind": "reset",
      "presentation": "Reset restores the first state and fixed defaults. Provide the accessible name Reset, keyboard operation, and visible focus.",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Chained hash-table lookup",
        "regions": [
          {
            "id": "query",
            "label": "Requested key",
            "values": [
              "act"
            ]
          },
          {
            "id": "hash",
            "label": "Hash function",
            "values": [
              "Character count modulo bucket count"
            ]
          },
          {
            "id": "bucket-0",
            "label": "Bucket 0",
            "values": [
              "Chain head"
            ]
          },
          {
            "id": "bucket-1",
            "label": "Bucket 1",
            "values": [
              "Empty"
            ]
          },
          {
            "id": "bucket-2",
            "label": "Bucket 2",
            "values": [
              "Empty"
            ]
          },
          {
            "id": "bucket-3",
            "label": "Bucket 3",
            "values": [
              "Chain head"
            ]
          },
          {
            "id": "entry-cat",
            "label": "Entry cat",
            "values": [
              "Key: cat",
              "Value: feline"
            ]
          },
          {
            "id": "entry-act",
            "label": "Entry act",
            "values": [
              "Key: act",
              "Value: perform"
            ]
          },
          {
            "id": "entry-pear",
            "label": "Entry pear",
            "values": [
              "Key: pear",
              "Value: fruit"
            ]
          }
        ],
        "links": [
          {
            "from": "query",
            "to": "hash",
            "label": "Input"
          },
          {
            "from": "bucket-0",
            "to": "entry-pear",
            "label": "Head"
          },
          {
            "from": "bucket-3",
            "to": "entry-cat",
            "label": "Head"
          },
          {
            "from": "entry-cat",
            "to": "entry-act",
            "label": "Next"
          }
        ],
        "states": [
          {
            "id": "request",
            "label": "Request the key",
            "short": "Request",
            "sentence": "The requested key is here.",
            "why": "The table already stores its entries. Use Next to look up act without scanning the entire table.",
            "active": [
              "query"
            ],
            "calloutRegion": "query",
            "readouts": [
              {
                "id": "bucket-count",
                "label": "Bucket count",
                "value": "4"
              },
              {
                "id": "hash-output",
                "label": "Hash output",
                "value": "Not computed"
              },
              {
                "id": "comparisons",
                "label": "Key comparisons",
                "value": "0"
              },
              {
                "id": "result",
                "label": "Returned value",
                "value": "Not returned"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Ready to hash the requested key."
              }
            ]
          },
          {
            "id": "hash-key",
            "label": "Compute the bucket",
            "short": "Hash",
            "sentence": "The hash function is here.",
            "why": "The requested key has three characters. Its character count modulo the bucket count determines the bucket address.",
            "active": [
              "hash"
            ],
            "calloutRegion": "hash",
            "readouts": [
              {
                "id": "bucket-count",
                "label": "Bucket count",
                "value": "4"
              },
              {
                "id": "hash-output",
                "label": "Hash output",
                "value": "3"
              },
              {
                "id": "comparisons",
                "label": "Key comparisons",
                "value": "0"
              },
              {
                "id": "result",
                "label": "Returned value",
                "value": "Not returned"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Bucket address computed; no stored keys compared."
              }
            ]
          },
          {
            "id": "open-bucket",
            "label": "Follow the bucket",
            "short": "Bucket",
            "sentence": "The selected bucket begins here.",
            "why": "Only this bucket's chain needs searching. The pear entry belongs to another bucket and remains untouched.",
            "active": [
              "bucket-3"
            ],
            "calloutRegion": "bucket-3",
            "readouts": [
              {
                "id": "bucket-count",
                "label": "Bucket count",
                "value": "4"
              },
              {
                "id": "hash-output",
                "label": "Hash output",
                "value": "3"
              },
              {
                "id": "comparisons",
                "label": "Key comparisons",
                "value": "0"
              },
              {
                "id": "result",
                "label": "Returned value",
                "value": "Not returned"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Follow the selected bucket's head link."
              }
            ]
          },
          {
            "id": "reject-collision",
            "label": "Reject the colliding key",
            "short": "Compare cat",
            "sentence": "The first candidate is here.",
            "why": "Cat and act share a hash output, but their keys differ. Follow Next within the chain instead of returning feline.",
            "active": [
              "entry-cat"
            ],
            "calloutRegion": "entry-cat",
            "readouts": [
              {
                "id": "bucket-count",
                "label": "Bucket count",
                "value": "4"
              },
              {
                "id": "hash-output",
                "label": "Hash output",
                "value": "3"
              },
              {
                "id": "comparisons",
                "label": "Key comparisons",
                "value": "1"
              },
              {
                "id": "result",
                "label": "Returned value",
                "value": "Not returned"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Key mismatch; continue along the same chain."
              }
            ]
          },
          {
            "id": "found",
            "label": "Return the matching value",
            "short": "Match act",
            "sentence": "The matching entry is here.",
            "why": "The exact key matches. Hashing narrowed the search; key comparison distinguished the colliding entries and selected the correct value.",
            "active": [
              "entry-act"
            ],
            "calloutRegion": "entry-act",
            "readouts": [
              {
                "id": "bucket-count",
                "label": "Bucket count",
                "value": "4"
              },
              {
                "id": "hash-output",
                "label": "Hash output",
                "value": "3"
              },
              {
                "id": "comparisons",
                "label": "Key comparisons",
                "value": "2"
              },
              {
                "id": "result",
                "label": "Returned value",
                "value": "perform"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Lookup complete; pear was never compared."
              }
            ]
          }
        ]
      }
    ]
  }
}
